Plugins.Require("pay_activity", "common.config.CommonAdActivityConfig")
---@type IPayActivity
local IPayActivity = Plugins.Require("pay_activity", "common.class.IPayActivity")
---@class CommonAdActivity : IPayActivity
local CommonAdActivity = class("CommonAdActivity", IPayActivity)
---@type CommonAdActivityConfig
local CommonAdActivityConfig = T(Global, "CommonAdActivityConfig")
---@type SPayActivityPkSender | CPayActivityPkSender
local PayActivityPkSender = T(Global, "PidPacketSender")
---@type uuid
local uuid = require "engine_base.util.uuid"
---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")
---@type EventConfig
local EventConfig = T(Global, "EventConfig")
EventConfig:registerEvent("ad_game_clicked", {
    ["item_id"] = "number",
    ["source"] = "string",
})
EventConfig:registerEvent("ad_game_rewarded", {
    ["item_id"] = "number",
    ["source"] = "string",
})

function CommonAdActivity:initDataInfo()
    self:initInfoKey("Times", 0)
    self:initInfoKey("Record", {})
    self:initInfoKey("Cycle", 0)
    self:initInfoKey("LoginUIDay", 0)
    local cfgs = CommonAdActivityConfig:getItemCfgs(self.activityId)
    for _, cfg in pairs(cfgs) do
        self:initInfoKey(PayActivityDefine.AdvertInfoKey.DayTimes .. cfg.tag, 0, true, false, cfg.dayMaxTimes >= 0)
        self:initInfoKey(PayActivityDefine.AdvertInfoKey.CoolingTime .. cfg.tag, 0, true, false, cfg.coolingTime > 0)
    end
    self:registerC2SFunc("tryGetReward")
    self:registerC2SFunc("setLoginUIDay")

    self.callbacks = {}
end

function CommonAdActivity:onSecondTick(curTime)
    if isClient then
        return
    end
    local newCycle = math.floor(curTime / DateUtil.getDaySeconds())
    local oldCycle = self.info:getValue("Cycle")
    if newCycle > oldCycle then
        self.info:setValue("Cycle", newCycle)
        self:resetTimes()
    end
end


function CommonAdActivity:onStart()
    if isClient then
        return
    end
    PayActivityPkSender:onGetWatchAdCache(self.player)
end

function CommonAdActivity:resetTimes()
    local cfgs = CommonAdActivityConfig:getItemCfgs(self.activityId)
    for _, cfg in pairs(cfgs) do
        self.info:setValue(PayActivityDefine.AdvertInfoKey.DayTimes .. cfg.tag, 0)
        self.info:setValue(PayActivityDefine.AdvertInfoKey.CoolingTime .. cfg.tag, 0)
    end
end

function CommonAdActivity:onCheckReset()
    local group = CommonAdActivityConfig:getRewardGroup(self.activityId)
    if not group then
        return
    end
    local record = self.info:getValue("Record")
    for _, reward in pairs(group.rewards) do
        if not TableUtil.tableContain(record, reward.id) then
            return
        end
    end
    self.info:setValue("Times", 0)
    self.info:setValue("Record", {})
end

function CommonAdActivity:tryGetReward(id)
    local cfg = CommonAdActivityConfig:getRewardById(id)
    if not cfg then
        return
    end
    if cfg.activityId ~= self.activityId then
        return
    end
    local times = self.info:getValue("Times")
    if times < cfg.needTimes then
        return
    end
    local record = self.info:getValue("Record")
    if TableUtil.tableContain(record, id) then
        return
    end
    if not self:canReward({ cfg.rewardId }) then
        return
    end
    if isClient then
        self:runServerFunc("tryGetReward", id)
    else
        if self:doReward({ cfg.rewardId }) then
            table.insert(record, id)
            self.info:setValue("Record", record)
            self:onCheckReset()
        end
    end
end

function CommonAdActivity:getCoolingTime(tag)
    return math.max(0, self.info:getValue(PayActivityDefine.AdvertInfoKey.CoolingTime .. tag) - os.time())
end

function CommonAdActivity:canWatchAdvert(tag)
    local cfg = CommonAdActivityConfig:getCfgByTag(tag)
    if not cfg then
        return false
    end
    if self:getCoolingTime(tag) > 0 then
        return false
    end
    if cfg.dayMaxTimes >= 0 and self.info:getValue(PayActivityDefine.AdvertInfoKey.DayTimes .. tag) >= cfg.dayMaxTimes then
        return false
    end
    if isClient then
        return isLocalWin or ClientHelper.getBoolPrefs("ShowVideoAd")
    else
        return true
    end
end

function CommonAdActivity:getAdLastTimes(tag)
    local cfg = CommonAdActivityConfig:getCfgByTag(tag)
    if not cfg then
        return 0, 1
    end
    local times = self.info:getValue(PayActivityDefine.AdvertInfoKey.DayTimes .. tag)
    return math.max(0, cfg.dayMaxTimes - times), cfg.dayMaxTimes
end

function CommonAdActivity:tryWatchAdvert(tag, rewardId)
    local cfg = CommonAdActivityConfig:getCfgByTag(tag)
    if not cfg then
        return
    end
    if not self:canWatchAdvert(tag) then
        UIHelper.showToast(Lang:getString("gui.ad.loading.hint"))
        return
    end
    local params = {}
    params.ad_type = cfg.type or "video"
    params.ad_game = GameType
    params.ad_uuid = uuid()
    params.ad_reward = rewardId
    local builder = DataBuilder.new():fromTable(params)
    ClientHelper.onWatchAd(cfg.id, builder:getData())
    ReportEvent.reportEvent(Game:getPlatformUserId(), "ad_game_clicked", false, {
        item_id = cfg.id,
        source = cfg.type or "video"
    })
end

function CommonAdActivity:onWatchAdvert(type, params)
    if isClient then
        return
    end
    --self.info:incValue("Times", 1)
    local builder = DataBuilder.new():fromData(params)
    PayActivityPkSender:onWatchAdSuccess(self.player, builder:getParam("ad_uuid"))
    local cfg = CommonAdActivityConfig:getItemCfgById(type)
    if not cfg then
        return
    end
    if not self:canWatchAdvert(cfg.tag) then
        return
    end
    if cfg.dayMaxTimes >= 0 then
        self.info:incValue(PayActivityDefine.AdvertInfoKey.DayTimes .. cfg.tag, 1)
    end
    if cfg.coolingTime > 0 then
        self.info:setValue(PayActivityDefine.AdvertInfoKey.CoolingTime .. cfg.tag, os.time() + cfg.coolingTime)
    end
    local rewardId = builder:getParam("ad_reward")
    if self:canReward({ tonumber(rewardId) }) then
        self:doReward({ tonumber(rewardId) })
    end
    ReportEvent.reportEvent(self.player.userId, "ad_game_rewarded", false, {
        item_id = cfg.id,
        source = cfg.type or "video"
    })
    local callback = self.callbacks[cfg.tag]
    if not callback then
        return
    end
    callback(self.player, builder:toTable())
end

---@param callback fun(player : SBasePlayer, params : table | nil)
function CommonAdActivity:registerAdCallback(tag, callback)
    self.callbacks[tag] = callback
end

function CommonAdActivity:interceptLoginUI()
    if GameType == "g1042" then
        return false
    end
    local oldDay = self.info:getValue("LoginUIDay")
    local newDay = math.floor(os.time() / DateUtil.getDaySeconds())
    if newDay > oldDay then
        self:runServerFunc("setLoginUIDay", newDay)
        return false
    else
        return true
    end
end

function CommonAdActivity:setLoginUIDay(day)
    self.info:setValue("LoginUIDay", day)
end

return CommonAdActivity